package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

@Timeout(60)
class LmdbBackupTransactionCostTest {

	@Test
	void durableTransactionsDoNotCreatePerTransactionStageFiles(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setBackupJournalEnabled(true)
				.setForceSync(true)
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		store.init();
		CountDownLatch publishing = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		try {
			assertTrue(store.isNativeQueryEngineEnabled());
			store.getBackingStore().backupPublisher().setBeforePublication(() -> {
				publishing.countDown();
				try {
					if (!release.await(30, TimeUnit.SECONDS)) {
						throw new IllegalStateException("Publication gate was not released");
					}
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new IllegalStateException(interrupted);
				}
			});
			var values = SimpleValueFactory.getInstance();
			for (int transaction = 0; transaction < 8; transaction++) {
				try (SailConnection connection = store.getConnection()) {
					connection.begin();
					connection.addStatement(values.createIRI("urn:backup:subject:" + transaction),
							values.createIRI("urn:backup:predicate"), values.createLiteral(transaction));
					connection.commit();
				}
				if (transaction == 0) {
					assertTrue(publishing.await(10, TimeUnit.SECONDS), "Publisher did not reach the gate");
				}
			}
			try (SailConnection connection = store.getConnection()) {
				assertEquals(8L, connection.size());
			}
			try (var files = Files.list(directory.resolve(PostCommitBackupPublisher.DIRECTORY))) {
				assertEquals(0L, files.filter(path -> path.getFileName().toString().endsWith(".stage")).count(),
						"Committed backup payloads must share the native transaction instead of forced stage files");
			}
		} finally {
			release.countDown();
			store.shutDown();
		}
	}
}
